const EVENTS = [{"id":"vizantia","y":600,"kind":"building","at":[28.98,41.01],"t":"Византия управлява Балканите","d":"Около 600 г. Балканите са част от Източната Римска империя — Византия. Столицата ѝ Константинопол е най-големият град в Европа, а храмът „Света София“ е чудо на строителството."},{"id":"slavs","y":610,"kind":"event","at":[23.6,43.4],"t":"Славяните се заселват","d":"От север, през река Дунав, идват славянски племена. Те се заселват из целия полуостров, орат земята и живеят в малки селища. По-късно стават част от българския народ.","path":[[25.5,47.6],[24.6,45.6],[23.9,43.9]]},{"id":"kubrat","y":632,"kind":"person","at":[36.7,45.3],"t":"Хан Кубрат и Стара Велика България","d":"Хан Кубрат обединява прабългарските племена край Азовско море. Византийците наричат неговата държава Стара Велика България. Столица е град Фанагория."},{"id":"snop","y":665,"kind":"event","at":[38.6,46.2],"t":"Снопът пръчки","d":"Легендата разказва, че преди да умре, Кубрат дал на синовете си сноп пръчки. Поотделно всяка пръчка се чупела лесно, а заедно — не. Така ги учел да бъдат единни."},{"id":"ongal","y":680,"kind":"battle","at":[28.75,45.3],"t":"Битката при Онгъла","d":"Синът на Кубрат, хан Аспарух, води своите хора до делтата на Дунав. Там, при Онгъла, той побеждава армията на византийския император Константин IV.","path":[[37.8,46.9],[34.5,46.9],[31.5,46.5],[29.4,45.6]]},{"id":"asparuh","y":681,"kind":"event","at":[27.12,43.38],"t":"Основаването на България","d":"Византия сключва мир с Аспарух и признава новата държава. Прабългари и славяни заживяват заедно, а столица става Плиска. Това е началото на България, която съществува и днес!"},{"id":"kuber","y":685,"kind":"person","at":[21.35,41.05],"t":"Кубер в Македония","d":"Друг син на Кубрат — Кубер — повежда своите хора на запад. Той се заселва в Керамисийското поле около днешния град Битоля, в Македония.","path":[[22.6,46.3],[21.9,43.6],[21.4,41.4]]},{"id":"madara","y":710,"kind":"building","at":[27.12,43.28],"t":"Мадарският конник","d":"Високо в скалата, 23 метра над земята, е издълбан конник, който пронизва лъв с копието си. Това е единственият скален релеф от Ранното средновековие в Европа. Около него има надписи за делата на българските ханове."},{"id":"tervel","y":718,"kind":"person","at":[28.6,41.25],"t":"Тервел спасява Константинопол","d":"През 717–718 г. арабите обсаждат Константинопол. Хан Тервел идва на помощ и ги разбива. Така българите помагат да се спре нашествието на арабите в Европа."},{"id":"krum","y":803,"kind":"person","at":[26.6,44.3],"t":"Хан Крум Страшни","d":"Крум разгромява аварите и разширява България далеч на северозапад. Той издава първите писани закони на страната — със строги наказания за крадци и лъжци."},{"id":"varbitsa","y":811,"kind":"battle","at":[26.65,42.97],"t":"Битката във Върбишкия проход","d":"Византийският император Никифор I опожарява Плиска. На връщане армията му попада в капан в планинския проход. Императорът загива, а Крум прави от черепа му чаша."},{"id":"omurtag","y":822,"kind":"person","at":[25.65,43.08],"t":"Хан Омуртаг Строителя","d":"Омуртаг сключва 30-годишен мир с Византия и строи дворци и крепости. Негов надпис гласи: „Човек и добре да живее, умира, и друг се ражда. Нека по-късно роденият, като гледа този надпис, да си спомня за онзи, който го е направил.“"},{"id":"kirilimetodii","y":863,"kind":"person","at":[22.94,40.64],"t":"Кирил и Методий","d":"Братята Кирил и Методий от Солун създават глаголицата — азбука за славяните. С нея превеждат свещените книги на славянски език, разбираем за всички."},{"id":"boris","y":864,"kind":"person","at":[27.12,43.38],"t":"Покръстването","d":"Княз Борис I приема християнството и покръства народа си. Така прабългари и славяни стават един народ с една вяра."},{"id":"kliment","y":886,"kind":"person","at":[20.8,41.12],"t":"Учениците идват в България","d":"Учениците на Кирил и Методий — Климент, Наум и Ангеларий — са приети радушно от княз Борис. Климент Охридски учи хиляди деца да четат и пишат."},{"id":"preslav","y":893,"kind":"event","at":[26.82,43.16],"t":"Преславският събор","d":"Столицата се мести от Плиска в Преслав. Славянският език става официален за държавата и църквата. В България е създадена кирилицата — азбуката, с която пишем и днес!"},{"id":"simeon","y":894,"kind":"person","at":[26.1,42.9],"t":"Цар Симеон Велики","d":"Симеон е учил в Константинопол и е много образован. Времето му наричат „Златен век“ на българската книжнина. При него България става една от най-големите държави в Европа."},{"id":"goldenchurch","y":908,"kind":"building","at":[26.95,43.05],"t":"Златната църква в Преслав","d":"Кръглата църква в Преслав е била украсена със злато, мрамор и керамика. В Преслав е намерена и прочутата рисувана керамична икона на Свети Теодор."},{"id":"aheloy","y":917,"kind":"battle","at":[27.6,42.65],"t":"Битката при Ахелой","d":"На 20 август 917 г. Симеон разбива огромна византийска армия край река Ахелой, до днешното Поморие. Това е една от най-големите битки в средновековна Европа."},{"id":"petar","y":927,"kind":"person","at":[26.6,43.35],"t":"Цар Петър и дългият мир","d":"Цар Петър сключва мир с Византия, който трае близо 40 години. Българската църква получава свой патриарх — първата славянска патриаршия."},{"id":"ivanrilski","y":930,"kind":"building","at":[23.34,42.13],"t":"Свети Иван Рилски","d":"Отшелникът Иван Рилски живее в пещера в Рила планина. Около него се събират ученици и така се ражда Рилският манастир — най-известният манастир в България."},{"id":"preslav971","y":971,"kind":"battle","at":[26.82,43.16],"t":"Падането на Преслав","d":"Киевският княз Светослав напада България. Византийският император Йоан Цимисхий го прогонва, но превзема Преслав и завладява Източна България."},{"id":"samuil","y":997,"kind":"person","at":[20.8,41.12],"t":"Цар Самуил","d":"Самуил продължава борбата от запад. Столицата му е в Охрид и на остров в Преспанското езеро. Близо 40 години той се бори срещу Византия."},{"id":"kleidion","y":1014,"kind":"battle","at":[23.1,41.36],"t":"Битката при Беласица","d":"Император Василий II обгражда българската армия в планината Беласица. Той ослепява пленените войници и ги връща при Самуил. Царят не издържа на мъката и умира."},{"id":"fall1018","y":1018,"kind":"event","at":[20.84,41.15],"t":"Под византийска власт","d":"През 1018 г. пада и Охрид. Близо 170 години България е част от Византия. Българите обаче пазят своя език, вяра и книги."},{"id":"delyan","y":1040,"kind":"event","at":[20.46,44.82],"t":"Въстанието на Петър Делян","d":"Петър Делян, който казва, че е внук на цар Самуил, вдига въстание в Белград и е провъзгласен за цар. Въстанието е потушено, но показва, че българите не са забравили своята държава."},{"id":"asen","y":1185,"kind":"event","at":[25.65,43.08],"t":"Въстанието на Асен и Петър","d":"Братята Асен и Петър вдигат въстание в Търново на празника на Свети Димитър. Така се ражда Второто българско царство. Столица става Търново с крепостта Царевец."},{"id":"kaloyan","y":1205,"kind":"battle","at":[26.56,41.68],"t":"Калоян побеждава рицарите","d":"Кръстоносците превземат Константинопол и основават Латинска империя. През 1205 г. цар Калоян ги разбива при Одрин и пленява император Балдуин."},{"id":"ivanasen","y":1230,"kind":"battle","at":[25.5,41.95],"t":"Иван Асен II и трите морета","d":"При Клокотница цар Иван Асен II побеждава епирския владетел Теодор Комнин. България отново стига до три морета — Черно, Бяло и Адриатическо."},{"id":"boyana","y":1259,"kind":"building","at":[23.27,42.65],"t":"Боянската църква","d":"Стенописите в Боянската църква са рисувани през 1259 г. Лицата изглеждат живи и изразителни — много преди италианския Ренесанс. Църквата е паметник на ЮНЕСКО."},{"id":"ivaylo","y":1277,"kind":"person","at":[27.2,43.7],"t":"Ивайло — царят-свинар","d":"Селянинът Ивайло, който пасял свине, събира войска и прогонва татарите, които ограбват страната. Народът го провъзгласява за цар! Такова нещо рядко се случва в историята."},{"id":"osmanli","y":1354,"kind":"event","at":[26.67,40.41],"t":"Османците идват в Европа","d":"Османските турци преминават от Мала Азия в Европа при Галиполи. Българските, сръбските и византийските владетели воюват помежду си и не успяват да ги спрат.","path":[[29.06,40.18],[27.6,40.35],[26.67,40.41],[26.56,41.68]]},{"id":"ivanaleksandar","y":1356,"kind":"person","at":[25.65,43.08],"t":"Цар Иван Александър","d":"Иван Александър поръчва прекрасни книги с рисунки, като Четвероевангелието, което днес се пази в Лондон. В него са нарисувани царят, царицата и децата им."},{"id":"tarnovo1393","y":1393,"kind":"battle","at":[25.65,43.08],"t":"Падането на Търново","d":"След тримесечна обсада османците превземат столицата Търново. Патриарх Евтимий води защитата на града. След падането той е изпратен на заточение."},{"id":"nikopol","y":1396,"kind":"battle","at":[24.9,43.7],"t":"Битката при Никопол","d":"Армия от европейски рицари се опитва да спре османците, но губи при Никопол. Пада и Видинското царство и цяла България е под османска власт за почти 500 години."},{"id":"varna1444","y":1444,"kind":"battle","at":[27.9,43.21],"t":"Битката при Варна","d":"Полско-унгарският крал Владислав III повежда кръстоносен поход, за да освободи Балканите. Той загива в битката край Варна и затова е наречен Варненчик."},{"id":"carigrad","y":1453,"kind":"battle","at":[28.98,41.01],"t":"Падането на Константинопол","d":"Султан Мехмед II превзема Константинопол. Византийската империя изчезва след повече от 1000 години. Градът става столица на Османската империя."},{"id":"chiprovtsi","y":1688,"kind":"event","at":[22.88,43.38],"t":"Чипровското въстание","d":"Жителите на Чипровци, богат град на рудари и златари, въстават срещу османците. Въстанието е потушено, но чипровските килими и днес са прочути."},{"id":"paisiy","y":1762,"kind":"person","at":[24.15,40.35],"t":"Паисий Хилендарски","d":"Монахът Паисий пише „История славянобългарска“ в Хилендарския манастир на Света гора. Той пита: „Поради что се срамиш да се наречеш болгарин?“ Така започва Българското възраждане."},{"id":"riben","y":1824,"kind":"event","at":[25.6,45.65],"t":"Рибният буквар","d":"Петър Берон издава буквар за деца. На последната страница има рисунка на делфин, затова го наричат „Рибния буквар“. По него учат деца в цялата страна."},{"id":"gabrovo","y":1835,"kind":"building","at":[25.32,42.87],"t":"Първото светско училище","d":"В Габрово, с помощта на Васил Априлов и Неофит Рилски, се открива първото българско светско училище. Там децата учат математика, история и география."},{"id":"rakovski","y":1862,"kind":"person","at":[20.46,44.82],"t":"Георги Раковски","d":"Раковски създава Първата българска легия в Белград — отряд доброволци, готови да се бият за свободата на България. Той пръв обмисля план за общо въстание."},{"id":"ekzarhia","y":1870,"kind":"event","at":[28.95,41.03],"t":"Българската екзархия","d":"След дълга борба султанът позволява на българите да имат своя църква — Екзархията. Така българите са признати като отделен народ в Османската империя."},{"id":"levski","y":1873,"kind":"person","at":[23.32,42.7],"t":"Васил Левски — Апостола","d":"Левски обикаля България и създава тайни комитети в стотици селища. Той мечтае за „чиста и свята република“ с равни права за всички. Обесен е в София през февруари 1873 г."},{"id":"april","y":1876,"kind":"event","at":[24.35,42.64],"t":"Априлското въстание","d":"През април 1876 г. въстават Копривщица, Панагюрище, Батак и много други селища. Въстанието е жестоко потушено, но светът научава за страданията на българите."},{"id":"botev","y":1876.4,"kind":"person","at":[23.55,43.2],"t":"Христо Ботев","d":"Поетът Христо Ботев превзема австрийския параход „Радецки“ на Дунав с около 200 четници. Те стигат до Врачанския Балкан, където Ботев загива. Стиховете му се учат и днес.","path":[[23.73,43.8],[23.62,43.5],[23.55,43.2]]},{"id":"shipka","y":1877,"kind":"battle","at":[25.32,42.75],"t":"Боевете на Шипка","d":"В Руско-турската война руски войници и български опълченци защитават прохода Шипка. Когато свършват патроните, те се бранят с камъни и дървета."},{"id":"osvobozhdenie","y":1878,"kind":"event","at":[28.82,40.96],"t":"Освобождението — 3 март 1878","d":"С мирния договор от Сан Стефано България отново е свободна държава след почти 500 години. 3 март днес е националният празник на България."},{"id":"berlin","y":1878.5,"kind":"event","at":[24.4,41.75],"t":"Берлинският договор","d":"Големите европейски държави решават, че голяма България им пречи. В Берлин я разделят: Княжество България, Източна Румелия под властта на султана, а Македония и Тракия остават в Османската империя."},{"id":"konstitucia","y":1879,"kind":"event","at":[25.65,43.08],"t":"Търновската конституция","d":"Учредителното събрание в Търново приема една от най-демократичните конституции в Европа. За столица е избрана София, а за княз — Александър Батенберг."},{"id":"saedinenie","y":1885,"kind":"event","at":[24.75,42.15],"t":"Съединението","d":"На 6 септември 1885 г. в Пловдив е обявено обединението на Княжество България и Източна Румелия. Голяма радост е за всички българи."},{"id":"slivnitsa","y":1885.5,"kind":"battle","at":[23.04,42.85],"t":"Битката при Сливница","d":"Сърбия напада България веднага след Съединението. Младата българска армия, водена от млади капитани, побеждава при Сливница. Войната е наречена „войната на капитаните срещу генералите“."},{"id":"nezavisimost","y":1908,"kind":"event","at":[25.65,43.08],"t":"Независимостта","d":"На 22 септември 1908 г. в църквата „Свети 40 мъченици“ в Търново княз Фердинанд обявява пълната независимост на България. Тя вече е царство, а Фердинанд — цар."},{"id":"nevski","y":1912,"kind":"building","at":[23.33,42.7],"t":"Храм „Свети Александър Невски“","d":"Храм-паметникът е строен цели 30 години в памет на загиналите за Освобождението. Златните му куполи блестят над София и днес."},{"id":"odrin","y":1912.8,"kind":"battle","at":[26.56,41.68],"t":"Балканската война","d":"България, Сърбия, Гърция и Черна гора се съюзяват срещу Османската империя и побеждават. Българската армия превзема силно укрепения Одрин през март 1913 г."},{"id":"mezhdusayuznicheska","y":1913,"kind":"event","at":[24,41.45],"t":"Междусъюзническата война","d":"Съюзниците се скарват за Македония. Срещу България се изправят всички съседи и тя губи войната. Запазва излаз на Бяло море, но губи Южна Добруджа."},{"id":"doyran","y":1917,"kind":"battle","at":[22.73,41.2],"t":"Първата световна война","d":"България влиза във войната на страната на Германия, за да спечели Македония. Войниците ѝ се бият храбро, например при Дойран, но войната е загубена."},{"id":"neuilly","y":1919,"kind":"event","at":[25.4,41.15],"t":"Ньойският договор","d":"След войната България губи Западна Тракия и излаза на Бяло море, както и Западните покрайнини. Трябва да плаща и големи обезщетения."},{"id":"dobrudzha","y":1940,"kind":"event","at":[27.83,43.57],"t":"Южна Добруджа се връща","d":"С Крайовската спогодба Южна Добруджа отново става част от България — без война. Тази граница е запазена и до днес."},{"id":"evrei","y":1943,"kind":"event","at":[23.32,42.7],"t":"Спасяването на българските евреи","d":"Във Втората световна война Германия иска евреите от България да бъдат изпратени в лагери на смъртта. Депутатът Димитър Пешев, митрополитите Стефан и Кирил и много граждани се противопоставят и близо 50 000 души са спасени. Евреите от Македония и Беломорска Тракия, тогава под българско управление, не са спасени."},{"id":"republika46","y":1946,"kind":"event","at":[23.32,42.7],"t":"Народната република","d":"След Втората световна война на власт идват комунистите, подкрепяни от Съветския съюз. С референдум през 1946 г. монархията е премахната, а малкият цар Симеон II напуска страната."},{"id":"kosmos","y":1979,"kind":"person","at":[24.72,43.13],"t":"Първият български космонавт","d":"Георги Иванов от Ловеч полита в космоса с кораба „Союз 33“. България става шестата страна в света с космонавт."},{"id":"1300","y":1981,"kind":"building","at":[26.93,43.27],"t":"1300 години България","d":"През 1981 г. България празнува 1300 години от основаването си. Над Шумен е построен огромният паметник „Създатели на българската държава“."},{"id":"demokracia","y":1989,"kind":"event","at":[23.32,42.7],"t":"10 ноември 1989","d":"Тодор Живков, управлявал 35 години, е свален. Започва преходът към демокрация: свободни избори, много партии и свобода на словото."},{"id":"futbol","y":1994,"kind":"event","at":[24.75,42.15],"t":"Четвърти в света!","d":"На Световното първенство по футбол в САЩ отборът на България, воден от Христо Стоичков, стига до полуфинал и завършва четвърти."},{"id":"nato","y":2004,"kind":"event","at":[23.32,42.7],"t":"България в НАТО","d":"На 29 март 2004 г. България става член на НАТО — съюз, в който държавите се защитават една друга."},{"id":"es","y":2007,"kind":"event","at":[23.32,42.7],"t":"България в Европейския съюз","d":"На 1 януари 2007 г. България става член на Европейския съюз. Кирилицата става третата официална азбука на ЕС — след латиницата и гръцката."},{"id":"shengen","y":2025,"kind":"event","at":[26.4,41.9],"t":"България в Шенген","d":"От 1 януари 2025 г. на границите с другите страни от Шенгенското пространство вече няма проверки. Хората пътуват свободно, без да показват паспорт."},{"id":"evro","y":2026,"kind":"event","at":[23.32,42.7],"t":"Еврото","d":"От 1 януари 2026 г. в България се плаща с евро. На центовете е Мадарският конник, на монетата от 1 евро — Свети Иван Рилски, а на 2 евро — Паисий Хилендарски."}];
const PHOTOS = CONTENT.photos;
